{"content":"from collections import deque
from math import gcd


def measure(bucket_one, bucket_two, goal, start_bucket):
    """Return (actions, goal bucket, other liters) for a shortest valid path."""
    if bucket_one <= 0 or bucket_two <= 0:
        raise ValueError("Bucket sizes must be positive.")
    if goal < 0:
        raise ValueError("The goal cannot be negative.")
    if start_bucket not in ("one", "two"):
        raise ValueError("The starting bucket must be 'one' or 'two'.")
    if goal > max(bucket_one, bucket_two) or goal % gcd(bucket_one, bucket_two):
        raise ValueError("The goal cannot be measured with these bucket sizes.")

    if start_bucket == "one":
        initial = (bucket_one, 0)
        forbidden = (0, bucket_two)
    else:
        initial = (0, bucket_two)
        forbidden = (bucket_one, 0)

    pending = deque([(initial, 1)])
    visited = {initial}
    while pending:
        (one, two), actions = pending.popleft()
        if one == goal:
            return actions, "one", two
        if two == goal:
            return actions, "two", one

        to_two = min(one, bucket_two - two)
        to_one = min(two, bucket_one - one)
        next_states = (
            (bucket_one, two),
            (one, bucket_two),
            (0, two),
            (one, 0),
            (one - to_two, two + to_two),
            (one + to_one, two - to_one),
        )
        for state in next_states:
            if state != forbidden and state not in visited:
                visited.add(state)
                pending.append((state, actions + 1))

    raise ValueError("The goal cannot be reached under the starting-bucket rule.")
