{"content":"import unittest

from two_bucket import measure


class MeasureTests(unittest.TestCase):
    def test_first_fill_counts_as_one_action(self):
        self.assertEqual(measure(3, 5, 3, "one"), (1, "one", 0))
        self.assertEqual(measure(3, 5, 5, "two"), (1, "two", 0))

    def test_pouring_from_either_starting_bucket(self):
        self.assertEqual(measure(3, 5, 1, "one"), (4, "one", 5))
        self.assertEqual(measure(3, 5, 1, "two"), (8, "two", 3))

    def test_goal_can_be_in_the_other_bucket(self):
        self.assertEqual(measure(3, 5, 4, "one"), (8, "two", 0))

    def test_filling_other_bucket_is_allowed_when_start_is_not_empty(self):
        self.assertEqual(measure(2, 3, 3, "one"), (2, "two", 2))
        self.assertEqual(measure(3, 2, 3, "two"), (2, "one", 2))

    def test_forbidden_state_cannot_provide_a_shortcut(self):
        self.assertEqual(measure(2, 3, 1, "one"), (4, "one", 3))
        self.assertEqual(measure(3, 2, 1, "two"), (4, "two", 3))

    def test_common_factor_does_not_prevent_reachable_goals(self):
        self.assertEqual(measure(6, 10, 2, "one"), (4, "one", 10))

    def test_zero_goal_still_requires_the_first_fill(self):
        self.assertEqual(measure(3, 5, 0, "one"), (1, "two", 3))

    def test_impossible_goals_raise_with_a_message(self):
        for args in ((2, 4, 3, "one"), (3, 5, 6, "two")):
            with self.subTest(args=args):
                with self.assertRaisesRegex(ValueError, r".+"):
                    measure(*args)

    def test_invalid_inputs_raise_with_a_message(self):
        for args in ((0, 5, 1, "one"), (3, -5, 1, "two"),
                     (3, 5, -1, "one"), (3, 5, 1, "three")):
            with self.subTest(args=args):
                with self.assertRaisesRegex(ValueError, r".+"):
                    measure(*args)


if __name__ == "__main__":
    unittest.main()
